def _apply(user_id,amount,operation,reason_code,idempotency_key,external_reference=None,metadata=None,compensates_transaction_id=None,db_path=None):
 uid=int(user_id);amount=int(amount);key=str(idempotency_key or '').strip();reason=str(reason_code or '').strip()
 if amount<=0:return {'success':False,'message':'Кількість кристалів має бути більшою за нуль.'}
 if not key:return {'success':False,'message':'idempotency_key є обов’язковим.'}
 if not reason:return {'success':False,'message':'reason_code є обов’язковим.'}
 c=_connect(db_path)
 try:
  c.execute('BEGIN IMMEDIATE');existing=c.execute('SELECT * FROM crystal_transactions WHERE idempotency_key=?',(key,)).fetchone()
  if existing:
   c.commit();return {'success':True,'idempotent_replay':True,'transaction':dict(existing),'balance':int(existing['balance_after'])}
  _ensure_wallet(c,uid);before=int(c.execute('SELECT balance FROM crystal_wallets WHERE user_id=?',(uid,)).fetchone()[0]);after=before+amount if operation=='credit' else before-amount
  if after<0:c.rollback();return {'success':False,'message':'Недостатньо кристалів.','balance':before}
  now=_utc();changed=c.execute('UPDATE crystal_wallets SET balance=?,updated_at=? WHERE user_id=? AND balance=?',(after,now,uid,before)).rowcount
  if changed!=1:raise RuntimeError('Баланс змінився. Операцію скасовано.')
  payload=json.dumps(metadata or {},ensure_ascii=False,sort_keys=True,separators=(',',':'))
  cur=c.execute('INSERT INTO crystal_transactions(user_id,operation,amount,reason_code,balance_before,balance_after,idempotency_key,external_reference,metadata_json,compensates_transaction_id,created_at) VALUES(?,?,?,?,?,?,?,?,?,?,?)',(uid,operation,amount,reason,before,after,key,external_reference,payload,compensates_transaction_id,now));tid=int(cur.lastrowid);c.commit()
  return {'success':True,'idempotent_replay':False,'transaction_id':tid,'operation':operation,'amount':amount,'balance_before':before,'balance_after':after,'balance':after}
 except sqlite3.IntegrityError:
  c.rollback();row=c.execute('SELECT * FROM crystal_transactions WHERE idempotency_key=?',(key,)).fetchone()
  if row:return {'success':True,'idempotent_replay':True,'transaction':dict(row),'balance':int(row['balance_after'])}
  raise
 except Exception:c.rollback();raise
 finally:c.close()

def get_crystal_wallet(user_id,db_path=None):
 c=_connect(db_path)
 try:
  c.execute('BEGIN IMMEDIATE');_ensure_wallet(c,user_id);row=c.execute('SELECT user_id,balance,created_at,updated_at FROM crystal_wallets WHERE user_id=?',(int(user_id),)).fetchone();c.commit();return dict(row)
 except Exception:c.rollback();raise
 finally:c.close()

def _ensure_wallet(c,user_id):
 uid=int(user_id);row=c.execute('SELECT user_id FROM users WHERE user_id=?',(uid,)).fetchone()
 if not row:raise ValueError('Акаунт не знайдено. Спочатку натисни /start.')
 now=_utc();c.execute('INSERT OR IGNORE INTO crystal_wallets(user_id,balance,created_at,updated_at) VALUES(?,0,?,?)',(uid,now,now))

def get_crystal_transactions(user_id,page=0,page_size=CRYSTAL_HISTORY_PAGE_SIZE,db_path=None):
 page=max(0,int(page));size=max(1,min(50,int(page_size)));c=_connect(db_path)
 try:
  rows=c.execute('SELECT * FROM crystal_transactions WHERE user_id=? ORDER BY id DESC LIMIT ? OFFSET ?',(int(user_id),size,page*size)).fetchall();total=c.execute('SELECT COUNT(*) FROM crystal_transactions WHERE user_id=?',(int(user_id),)).fetchone()[0];return {'items':[dict(x) for x in rows],'page':page,'total':int(total),'has_next':(page+1)*size<int(total)}
 finally:c.close()

def compensate_crystal_transaction(original_transaction_id,idempotency_key,reason_code='dev_compensation',db_path=None):
 c=_connect(db_path)
 try:row=c.execute('SELECT * FROM crystal_transactions WHERE id=?',(int(original_transaction_id),)).fetchone()
 finally:c.close()
 if not row:return {'success':False,'message':'Початкову транзакцію не знайдено.'}
 func=debit_crystals if row['operation']=='credit' else credit_crystals
 result=func(int(row['user_id']),int(row['amount']),reason_code,idempotency_key,external_reference=f"compensates:{int(row['id'])}",metadata={'original_transaction_id':int(row['id'])},db_path=db_path)
 if result.get('success') and not result.get('idempotent_replay'):
  c=_connect(db_path)
  try:c.execute('UPDATE crystal_transactions SET compensates_transaction_id=? WHERE id=? AND compensates_transaction_id IS NULL',(int(row['id']),int(result['transaction_id'])));c.commit()
  finally:c.close()
 return result

def execute_admin_adjustment(admin_user_id,target_user_id,operation,requested_amount,reason,idempotency_key,db_path=None):
 key=str(idempotency_key or '').strip()
 if not key:return {'success':False,'message':'Відсутній idempotency key.'}
 c=_connect(db_path)
 try:
  c.execute('BEGIN IMMEDIATE');existing=c.execute('SELECT * FROM admin_crystal_credit_audit WHERE idempotency_key=?',(key,)).fetchone()
  if existing:c.commit();return {'success':True,'idempotent_replay':True,'audit':dict(existing),'balance':int(existing['balance_after'])}
  if not is_admin(admin_user_id):raise ValueError('Доступ заборонено.')
  target=int(target_user_id);amount=int(requested_amount);op=str(operation);reason=str(reason or '').strip();limit=ROM_ADMIN_CRYSTAL_CREDIT_MAX if op=='credit' else ROM_ADMIN_CRYSTAL_DEBIT_MAX
  if op not in ('credit','debit') or amount<1 or amount>limit or not reason:raise ValueError('Параметри операції більше не валідні.')
  if not c.execute('SELECT 1 FROM users WHERE user_id=?',(target,)).fetchone():raise ValueError('Користувача не знайдено.')
  now=_utc();c.execute('INSERT OR IGNORE INTO crystal_wallets(user_id,balance,created_at,updated_at) VALUES(?,0,?,?)',(target,now,now));before=int(c.execute('SELECT balance FROM crystal_wallets WHERE user_id=?',(target,)).fetchone()[0]);actual=amount if op=='credit' else min(amount,before)
  if actual<=0:raise ValueError('У користувача немає кристалів для вилучення.')
  after=before+actual if op=='credit' else before-actual
  changed=c.execute('UPDATE crystal_wallets SET balance=?,updated_at=? WHERE user_id=? AND balance=?',(after,now,target,before)).rowcount
  if changed!=1:raise RuntimeError('Баланс змінився. Операцію скасовано.')
  txkey='admin:'+key;cur=c.execute('INSERT INTO crystal_transactions(user_id,operation,amount,reason_code,balance_before,balance_after,idempotency_key,external_reference,metadata_json,created_at) VALUES(?,?,?,?,?,?,?,?,?,?)',(target,op,actual,'admin_crystal_'+op,before,after,txkey,key,json.dumps({'admin_operation':True,'requested_amount':amount,'reason':reason},ensure_ascii=False,sort_keys=True),now));txid=int(cur.lastrowid)
  cur=c.execute('INSERT INTO admin_crystal_credit_audit(admin_user_id,target_user_id,operation,requested_amount,actual_amount,balance_before,balance_after,reason,idempotency_key,crystal_transaction_id,created_at) VALUES(?,?,?,?,?,?,?,?,?,?,?)',(int(admin_user_id),target,op,amount,actual,before,after,reason,key,txid,now));aid=int(cur.lastrowid);c.commit();return {'success':True,'idempotent_replay':False,'audit_id':aid,'transaction_id':txid,'operation':op,'requested_amount':amount,'actual_amount':actual,'balance_before':before,'balance_after':after,'balance':after,'clamped':op=='debit' and actual<amount}
 except Exception as e:c.rollback();return {'success':False,'message':f'Операцію скасовано: {e}'}
 finally:c.close()

def purchase_crystal_shop_item(user_id,item_id,quantity,idempotency_key,db_path=None):
 try:uid=int(user_id);iid=int(item_id);qty=int(quantity)
 except Exception:return {'success':False,'message':'❌ Некоректні дані покупки.'}
 key=str(idempotency_key or '').strip()
 if iid not in CRYSTAL_SHOP_CATALOG or qty<=0 or not key:return {'success':False,'message':'❌ Некоректна або неповна покупка.'}
 c=_connect(db_path)
 try:
  c.execute('BEGIN IMMEDIATE');old=c.execute('SELECT * FROM crystal_shop_purchases WHERE idempotency_key=?',(key,)).fetchone()
  if old:c.commit();return {'success':True,'idempotent_replay':True,'purchase':dict(old),'balance':int(old['balance_after'])}
  allowed={501:{'crystal_shop'},602:{'crystal_shop'},728:{'crystal_shop'},502:{'crystal_shop'}}
  if 'crystal_shop' not in allowed.get(iid,set()):c.rollback();return {'success':False,'message':'❌ Джерело видачі заборонене.'}
  wallet=c.execute('SELECT balance FROM crystal_wallets WHERE user_id=?',(uid,)).fetchone();item=c.execute('SELECT id FROM items WHERE id=?',(iid,)).fetchone()
  if not wallet or not item:c.rollback();return {'success':False,'message':'❌ Гаманець або предмет не знайдено.'}
  before=int(wallet[0]);unit=int(CRYSTAL_SHOP_CATALOG[iid]['price']);total=unit*qty;used,cap,needed,max_stack=_capacity(c,uid,iid,qty)
  if used+needed>cap:c.rollback();return {'success':False,'message':'🎒 Сумка переповнена. Кристали не списано.','balance':before}
  if before<total:c.rollback();return {'success':False,'message':'❌ Недостатньо кристалів.','balance':before}
  after=before-total;now=_utc();changed=c.execute('UPDATE crystal_wallets SET balance=?,updated_at=? WHERE user_id=? AND balance=?',(after,now,uid,before)).rowcount
  if changed!=1:raise RuntimeError('Баланс змінився. Покупку скасовано.')
  tx_key='shop:debit:'+key;cur=c.execute("INSERT INTO crystal_transactions(user_id,operation,amount,reason_code,balance_before,balance_after,idempotency_key,external_reference,metadata_json,created_at) VALUES(?,?,?,?,?,?,?,?,?,?)",(uid,'debit',total,'crystal_shop_purchase',before,after,tx_key,key,json.dumps({'item_id':iid,'quantity':qty},sort_keys=True),now));txid=int(cur.lastrowid)
  inv_id=_stack(c,uid,iid,qty,max_stack);grant_key='shop:grant:'+key;cur=c.execute('INSERT INTO premium_item_grants(user_id,item_id,quantity,source,idempotency_key,external_reference,metadata_json,created_at) VALUES(?,?,?,?,?,?,?,?)',(uid,iid,qty,'crystal_shop',grant_key,key,json.dumps({'total_price':total},sort_keys=True),now));gid=int(cur.lastrowid)
  cur=c.execute('INSERT INTO crystal_shop_purchases(user_id,item_id,quantity,unit_price,total_price,balance_before,balance_after,idempotency_key,crystal_transaction_id,premium_grant_id,created_at) VALUES(?,?,?,?,?,?,?,?,?,?,?)',(uid,iid,qty,unit,total,before,after,key,txid,gid,now));pid=int(cur.lastrowid);c.commit();return {'success':True,'idempotent_replay':False,'purchase_id':pid,'transaction_id':txid,'grant_id':gid,'inventory_id':inv_id,'item_id':iid,'name':CRYSTAL_SHOP_CATALOG[iid]['name'],'quantity':qty,'unit_price':unit,'total_price':total,'balance_before':before,'balance_after':after,'balance':after}
 except Exception as e:c.rollback();return {'success':False,'message':f'❌ Покупку скасовано: {e}'}
 finally:c.close()

def purchase_crystal_bag_expansion(user_id,target_capacity,idempotency_key,db_path=None):
 uid=int(user_id);target=int(target_capacity);key=str(idempotency_key or '').strip()
 if not key:return {'success':False,'message':'❌ Відсутній ключ операції.'}
 c=_connect(db_path)
 try:
  c.execute('BEGIN IMMEDIATE')
  previous=c.execute('SELECT * FROM account_bag_expansion_purchases WHERE idempotency_key=?',(key,)).fetchone()
  if previous:
   c.commit();row=dict(previous);row.update({'success':True,'idempotent_replay':True,'current_capacity':int(row['to_capacity']),'balance':int(row['balance_after'])});return row
  state=_state(c,uid)
  if not state:c.rollback();return {'success':False,'message':'❌ Користувача не знайдено.'}
  if state['maximum_reached']:c.rollback();return {**state,'success':False,'message':f"🎒 Сумка вже має максимальну місткість: {state['current_capacity']} слотів."}
  tier=BAG_EXPANSION_TIERS.get(state['current_capacity'])
  if not tier or target!=tier['target_capacity']:c.rollback();return {**state,'success':False,'message':'❌ Доступне лише наступне послідовне розширення сумки.'}
  price=int(tier['price']);before=int(state['balance'])
  if before<price:c.rollback();return {**state,'success':False,'message':'❌ Недостатньо кристалів.'}
  after=before-price;now=_utc();txkey='bag_expansion:debit:'+key
  tx=c.execute("INSERT INTO crystal_transactions(user_id,operation,amount,reason_code,balance_before,balance_after,idempotency_key,external_reference,metadata_json,created_at) VALUES(?,?,?,?,?,?,?,?,?,?)",(uid,'debit',price,'bag_expansion_purchase',before,after,txkey,key,json.dumps({'from_capacity':state['current_capacity'],'to_capacity':target},sort_keys=True),now));txid=int(tx.lastrowid)
  changed=c.execute('UPDATE crystal_wallets SET balance=?,updated_at=? WHERE user_id=? AND balance=?',(after,now,uid,before)).rowcount
  if changed!=1:raise RuntimeError('wallet concurrent update')
  changed=c.execute('UPDATE users SET bag_slots=? WHERE user_id=? AND COALESCE(bag_slots,60)=?',(target,uid,state['current_capacity'])).rowcount
  if changed!=1:raise RuntimeError('bag capacity concurrent update')
  cur=c.execute('INSERT INTO account_bag_expansion_purchases(user_id,from_capacity,to_capacity,crystal_price,balance_before,balance_after,idempotency_key,crystal_transaction_id,created_at) VALUES(?,?,?,?,?,?,?,?,?)',(uid,state['current_capacity'],target,price,before,after,key,txid,now));pid=int(cur.lastrowid);c.commit();return {'success':True,'idempotent_replay':False,'purchase_id':pid,'transaction_id':txid,'from_capacity':state['current_capacity'],'to_capacity':target,'current_capacity':target,'price':price,'balance_before':before,'balance_after':after,'balance':after}
 except sqlite3.IntegrityError:
  c.rollback();row=c.execute('SELECT * FROM account_bag_expansion_purchases WHERE idempotency_key=?',(key,)).fetchone()
  if row:
   data=dict(row);data.update({'success':True,'idempotent_replay':True,'current_capacity':int(data['to_capacity']),'balance':int(data['balance_after'])});return data
  return {'success':False,'message':'❌ Це розширення вже придбано.'}
 except Exception as error:c.rollback();return {'success':False,'message':f'❌ Покупку не завершено: {error}'}
 finally:c.close()
